#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long H, W, d;
    cin >> H >> W >> d;

    // Find one representation:
    // d = a^2 + b^2 with a,b >= 0
    // It is guaranteed that a solution exists, so such (a,b) exists.
    long long a = -1, b = -1;
    for (long long x = 0; x * x <= d; ++x) {
        long long y2 = d - x * x;
        long long y = sqrt((long double)y2);
        while ((y + 1) * (y + 1) <= y2) ++y;
        while (y * y > y2) --y;
        if (y * y == y2) {
            a = x;
            b = y;
            break;
        }
    }

    // 2-coloring by parity of floor((a*x + b*y)/d),
    // and another independent 2-coloring by parity of floor((b*x - a*y)/d).
    // Combining them gives 4 colors.
    //
    // For any two cells whose squared Euclidean distance is d,
    // their difference vector is one of (±a, ±b) or (±b, ±a),
    // which flips at least one of these two parities.

    for (long long i = 0; i < H; ++i) {
        for (long long j = 0; j < W; ++j) {
            long long p = (long long)floor((long double)(a * i + b * j) / d) & 1LL;
            long long q = (long long)floor((long double)(b * i - a * j) / d) & 1LL;
            int color = (int)(p * 2 + q); // 0..3
            cout << color << (j + 1 == W ? '\n' : ' ');
        }
    }

    return 0;
}

