import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int H = fs.nextInt();
        int W = fs.nextInt();
        long d = fs.nextLong();

        // Let d = 2^k * odd.
        // If d is odd:
        //   color = ((x+y)&1) * 2 + (f(x,y)&1)
        // where f(x,y) = ((x+y)/2) mod 2 after rotating coordinates.
        //
        // More generally, for d:
        // Let t be the exponent of 2 in d.
        // Define u = x + y, v = x - y.
        // Then color by the t-th bit of u and v:
        //   a = ((u mod 2^(t+1)) >= 2^t) ? 1 : 0
        //   b = ((v mod 2^(t+1)) >= 2^t) ? 1 : 0
        //   color = a*2 + b
        //
        // This works because for any pair at Manhattan distance exactly d,
        // after rotation:
        //   (Δu, Δv) = (p+q, p-q), where |p|+|q| = d
        // and both Δu, Δv are multiples of 2^t but not both multiples of 2^(t+1),
        // so at least one of the t-th bits differs.

        int t = 0;
        long tmp = d;
        while ((tmp & 1L) == 0) {
            t++;
            tmp >>= 1;
        }

        long mod = 1L << (t + 1);
        long half = 1L << t;

        char[] map = {'R', 'Y', 'G', 'B'};
        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                long u = (long) i + j;
                long v = (long) i - j;

                long um = floorMod(u, mod);
                long vm = floorMod(v, mod);

                int a = (um >= half) ? 1 : 0;
                int b = (vm >= half) ? 1 : 0;

                int color = a * 2 + b;
                sb.append(map[color]);
            }
            sb.append('\n');
        }

        System.out.print(sb.toString());
    }

    static long floorMod(long x, long m) {
        long r = x % m;
        return r < 0 ? r + m : r;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
